// Ledgeline core: due dates, ageing, overdue refresh, expense-claim workflow.

type InvoiceStatus = 'Draft' | 'Submitted' | 'Approved' | 'Paid' | 'Overdue' | 'Cancelled';
type ClaimStatus = 'Draft' | 'Submitted' | 'Approved' | 'Rejected' | 'Reimbursed';
type ExpenseCategory = 'Travel' | 'Meals' | 'Equipment' | 'Software' | 'Other';

interface Invoice {
  id: string;
  number: string;
  supplierId: string;
  supplierName?: string;
  issueDate: string;
  dueDate: string;
  amountCents: number;
  taxCents: number;
  status: InvoiceStatus;
  notes?: string;
}

interface ExpenseClaimInput {
  id?: string;
  employeeName: string;
  dateIncurred: string;
  category: ExpenseCategory;
  amountCents: number;
  receiptReference: string;
  status?: ClaimStatus;
  decisionNote?: string;
}

interface ExpenseClaim {
  id: string;
  employeeName: string;
  dateIncurred: string;
  category: ExpenseCategory;
  amountCents: number;
  receiptReference: string;
  status: ClaimStatus;
  decisionNote: string;
}

interface ClaimStore {
  claims: ExpenseClaim[];
}

interface ClaimPersistence {
  load(): Promise<ClaimStore>;
  save(store: ClaimStore): Promise<void>;
}

interface MutationResult {
  ok: boolean;
  claim: ExpenseClaim | null;
  error: string;
}

const PERSISTENCE_UNAVAILABLE: string = 'Persistence backend is unavailable';
const WRITE_FAILED: string = 'Save failed: persisted state left unchanged';
const REJECTION_NOTE_MIN_LENGTH: number = 8;

const claimStore: ClaimStore = { claims: [] };
let claimPersistence: ClaimPersistence | null = null;
let claimSequence: number = 0;

/**
 * Register the local persistence adapter used by the expense-claim workflow.
 * Passing null swaps in the in-memory fallback (still deterministic).
 */
function configureClaimPersistence(persistence: ClaimPersistence | null): void {
  claimPersistence = persistence;
}

function nextId(prefix: string): string {
  claimSequence += 1;
  const padded: string = String(claimSequence);
  return prefix + '-' + '00000000000000000000000000'.slice(0, Math.max(0, 26 - padded.length)) + padded;
}

function cloneClaim(claim: ExpenseClaim): ExpenseClaim {
  return {
    id: claim.id,
    employeeName: claim.employeeName,
    dateIncurred: claim.dateIncurred,
    category: claim.category,
    amountCents: claim.amountCents,
    receiptReference: claim.receiptReference,
    status: claim.status,
    decisionNote: claim.decisionNote
  };
}

function cloneStore(store: ClaimStore): ClaimStore {
  const claims: ExpenseClaim[] = [];
  for (let i: number = 0; i < store.claims.length; i += 1) {
    claims.push(cloneClaim(store.claims[i]));
  }
  return { claims: claims };
}

function loadClaimStore(): Promise<ClaimStore> {
  return new Promise<ClaimStore>((resolve: (value: ClaimStore) => void, reject: (reason: Error) => void): void => {
    if (claimPersistence !== null) {
      claimPersistence.load().then((store: ClaimStore): void => {
        resolve(cloneStore(store));
      }).catch((): void => {
        reject(new Error(PERSISTENCE_UNAVAILABLE));
      });
      return;
    }
    resolve(cloneStore(claimStore));
  });
}

function commitClaimStore(store: ClaimStore): Promise<void> {
  return new Promise<void>((resolve: () => void, reject: (reason: Error) => void): void => {
    if (claimPersistence !== null) {
      claimPersistence.save(cloneStore(store)).then((): void => {
        resolve();
      }).catch((): void => {
        reject(new Error(WRITE_FAILED));
      });
      return;
    }
    claimStore.claims = cloneStore(store).claims;
    resolve();
  });
}

function findClaim(store: ClaimStore, claimId: string): ExpenseClaim | null {
  for (let i: number = 0; i < store.claims.length; i += 1) {
    if (store.claims[i].id === claimId) {
      return store.claims[i];
    }
  }
  return null;
}

function toUtcMillis(dateText: string): number {
  const parts: string[] = dateText.split('-');
  if (parts.length !== 3) {
    return Number.NaN;
  }
  const year: number = Number(parts[0]);
  const month: number = Number(parts[1]);
  const day: number = Number(parts[2]);
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
    return Number.NaN;
  }
  return Date.UTC(year, month - 1, day);
}

function pad2(value: number): string {
  return value < 10 ? '0' + String(value) : String(value);
}

function formatIsoUtc(millis: number): string {
  const d: Date = new Date(millis);
  return String(d.getUTCFullYear()) + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate());
}

const DAY_MS: number = 86400000;

/**
 * Compute a due date as the issue date plus the supplier's payment terms in days,
 * using UTC calendar arithmetic. Returns an ISO yyyy-mm-dd date string.
 * // req-3
 */
function computeDueDate(issueDate: string, paymentTermsDays: number): string {
  const issueMillis: number = toUtcMillis(issueDate);
  const terms: number = Number.isFinite(paymentTermsDays) ? Math.trunc(paymentTermsDays) : 0;
  if (Number.isNaN(issueMillis)) {
    return '';
  }
  return formatIsoUtc(issueMillis + terms * DAY_MS);
}

/**
 * Compute the age of an invoice in whole days since its due date, measured at UTC
 * midnight of today (or a supplied reference date). Negative values mean not yet due.
 * // req-1
 */
function computeAge(dueDate: string, today?: string): number {
  const dueMillis: number = toUtcMillis(dueDate);
  if (Number.isNaN(dueMillis)) {
    return 0;
  }
  let todayMillis: number;
  if (typeof today === 'string' && today.length > 0) {
    todayMillis = toUtcMillis(today);
  } else {
    todayMillis = Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate());
  }
  if (Number.isNaN(todayMillis)) {
    return 0;
  }
  return Math.floor((todayMillis - dueMillis) / DAY_MS);
}

/**
 * Recompute the Overdue flag for every stored invoice from its due date and status.
 * An invoice is Overdue only when its due date is strictly before today and its
 * status is neither Paid nor Cancelled; the input array is never mutated.
 * // req-4
 */
function refreshOverdueStatuses(invoices: Invoice[], today?: string): Invoice[] {
  let todayMillis: number;
  if (typeof today === 'string' && today.length > 0) {
    todayMillis = toUtcMillis(today);
  } else {
    todayMillis = Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate());
  }
  const result: Invoice[] = [];
  for (let i: number = 0; i < invoices.length; i += 1) {
    const invoice: Invoice = invoices[i];
    const dueMillis: number = toUtcMillis(invoice.dueDate);
    const terminal: boolean = invoice.status === 'Paid' || invoice.status === 'Cancelled';
    const past: boolean = !Number.isNaN(dueMillis) && !Number.isNaN(todayMillis) && dueMillis < todayMillis;
    let status: InvoiceStatus = invoice.status;
    if (terminal) {
      status = invoice.status;
    } else if (past) {
      status = 'Overdue';
    } else if (invoice.status === 'Overdue') {
      status = 'Submitted';
    }
    result.push({
      id: invoice.id,
      number: invoice.number,
      supplierId: invoice.supplierId,
      supplierName: invoice.supplierName,
      issueDate: invoice.issueDate,
      dueDate: invoice.dueDate,
      amountCents: invoice.amountCents,
      taxCents: invoice.taxCents,
      status: status,
      notes: invoice.notes
    });
  }
  return result;
}

/**
 * Persist a new expense claim in Submitted status, charging the receipt reference
 * and integer-pence amount to the submitting employee.
 * // req-5
 */
async function submitExpenseClaim(input: ExpenseClaimInput): Promise<ExpenseClaim> {
  const store: ClaimStore = await loadClaimStore();
  const identifier: string = typeof input.id === 'string' && input.id.length > 0 ? input.id : nextId('claim');
  const amountCents: number = Number.isFinite(input.amountCents) ? Math.trunc(input.amountCents) : 0;
  const claim: ExpenseClaim = {
    id: identifier,
    employeeName: typeof input.employeeName === 'string' ? input.employeeName : '',
    dateIncurred: typeof input.dateIncurred === 'string' ? input.dateIncurred : '',
    category: input.category,
    amountCents: amountCents,
    receiptReference: typeof input.receiptReference === 'string' ? input.receiptReference : '',
    status: 'Submitted',
    decisionNote: typeof input.decisionNote === 'string' ? input.decisionNote : ''
  };
  const next: ClaimStore = cloneStore(store);
  next.claims.push(claim);
  await commitClaimStore(next);
  return cloneClaim(claim);
}

/**
 * Apply a monetary/status decision to a stored claim without ever writing a partial
 * record: the candidate store is validated in full, then committed atomically.
 */
async function mutateClaim(claimId: string, mutate: (claim: ExpenseClaim) => MutationResult): Promise<ExpenseClaim> {
  const store: ClaimStore = await loadClaimStore();
  const target: ExpenseClaim | null = findClaim(store, claimId);
  if (target === null) {
    throw new Error('Expense claim not found: ' + claimId);
  }
  const next: ClaimStore = cloneStore(store);
  const editable: ExpenseClaim | null = findClaim(next, claimId);
  if (editable === null) {
    throw new Error('Expense claim not found: ' + claimId);
  }
  const outcome: MutationResult = mutate(editable);
  if (!outcome.ok) {
    throw new Error(outcome.error);
  }
  if (outcome.claim !== null) {
    editable.status = outcome.claim.status;
    editable.decisionNote = outcome.claim.decisionNote;
  }
  await commitClaimStore(next);
  return cloneClaim(editable);
}

/**
 * Reject a submitted expense claim; the decision note must be at least 8 characters.
 * A claim that is already rejected, reimbursed or otherwise not Submitted is a no-op.
 * // req-5
 */
async function rejectExpenseClaim(claimId: string, decisionNote: string): Promise<ExpenseClaim> {
  const note: string = typeof decisionNote === 'string' ? decisionNote : '';
  if (note.length < REJECTION_NOTE_MIN_LENGTH) {
    throw new Error('Decision note must be at least ' + String(REJECTION_NOTE_MIN_LENGTH) + ' characters');
  }
  return mutateClaim(claimId, (claim: ExpenseClaim): MutationResult => {
    if (claim.status === 'Rejected') {
      return { ok: false, claim: null, error: 'Claim is already Rejected and stays rejected' };
    }
    if (claim.status === 'Reimbursed') {
      return { ok: false, claim: null, error: 'Claim is Reimbursed and can no longer be rejected' };
    }
    if (claim.status !== 'Submitted') {
      return { ok: false, claim: null, error: 'Claim must be Submitted to reject, current status: ' + claim.status };
    }
    return {
      ok: true,
      claim: { id: claim.id, employeeName: claim.employeeName, dateIncurred: claim.dateIncurred, category: claim.category, amountCents: claim.amountCents, receiptReference: claim.receiptReference, status: 'Rejected', decisionNote: note },
      error: ''
    };
  });
}

/**
 * Mark an approved expense claim as Reimbursed. A rejected claim can never be
 * reimbursed and an approved claim can never be re-approved.
 * // req-5
 */
async function reimburseExpenseClaim(claimId: string): Promise<ExpenseClaim> {
  return mutateClaim(claimId, (claim: ExpenseClaim): MutationResult => {
    if (claim.status === 'Rejected') {
      return { ok: false, claim: null, error: 'A rejected claim can never be reimbursed' };
    }
    if (claim.status === 'Reimbursed') {
      return { ok: false, claim: null, error: 'Claim is already Reimbursed' };
    }
    if (claim.status !== 'Approved') {
      return { ok: false, claim: null, error: 'Claim must be Approved to reimburse, current status: ' + claim.status };
    }
    return {
      ok: true,
      claim: { id: claim.id, employeeName: claim.employeeName, dateIncurred: claim.dateIncurred, category: claim.category, amountCents: claim.amountCents, receiptReference: claim.receiptReference, status: 'Reimbursed', decisionNote: claim.decisionNote },
      error: ''
    };
  });
}
export { computeDueDate, computeAge, refreshOverdueStatuses, submitExpenseClaim, rejectExpenseClaim, reimburseExpenseClaim };

